export const EXEC_MOD_SOURCES = {
  "construct-beacon": {
    "Cargo.toml": "[package]\nname = \"construct-beacon\"\ndescription = \"Presence beacon: a mod that counts the players in its grid and answers `present`\"\nversion = \"0.1.0\"\nedition = \"2024\"\npublish = false\n\n[lib]\ncrate-type = [\"cdylib\", \"rlib\"]\n\n[dependencies]\n# Crowdy Studio's build replaces this line with the platform's copy of ckx-sdk.\nckx-sdk = \"0.6.0\"\nserde = { version = \"1\", features = [\"derive\"] }\n",
    "src/lib.rs": "//! Presence beacon: a mod that counts the players standing in its grid and answers `present` with\n//! the count, the smallest piece of server authority a game (or a player) can ask a grid for.\n//!\n//! A mod is a player's code on a grid they own: one instance per grid, keyed by the grid id, run\n//! as its owner. It reads only its own grid through the node API (`grids.get`, `world.actors`),\n//! hears actors arrive and leave through `on_world`, and answers the players who call it\n//! (`mod:<name>`, with the grid id as the key). It calls no other node and sends no realtime\n//! events.\n//!\n//! Endpoints: `present` and `state`.\n\nuse ckx_sdk::prelude::*;\n\n/// Count again this often too: world events can be lost.\nconst COUNT_EVERY_MS: u64 = 10_000;\n/// The most chunks one count reads; a claimed chunk is a grid of one.\nconst MAX_CHUNKS: usize = 27;\n\n#[derive(Serialize, Deserialize, Default, Debug, PartialEq)]\npub struct Beacon {\n    pub grid: u64,\n    /// The grid's low and high chunk, read once.\n    pub bounds: Option<([i64; 3], [i64; 3])>,\n    pub present: usize,\n    pub counted_at: u64,\n}\n\n#[derive(Serialize)]\nstruct Present {\n    present: usize,\n}\n\n/// The chunks of a box, x fastest, at most `max` of them.\npub fn chunks(low: [i64; 3], high: [i64; 3], max: usize) -> Vec<ChunkPos> {\n    let mut out = Vec::new();\n    for y in low[1]..=high[1] {\n        for z in low[2]..=high[2] {\n            for x in low[0]..=high[0] {\n                if out.len() == max {\n                    return out;\n                }\n                out.push(ChunkPos::new(x, y, z));\n            }\n        }\n    }\n    out\n}\n\n/// Whether a batch of world events may have changed who is here.\npub fn actors_moved(events: &[WorldEvent]) -> bool {\n    events.iter().any(|e| e.kind == WorldEvent::ACTORS)\n}\n\nimpl Beacon {\n    fn bounds(&mut self, ctx: &Ctx) -> Result<([i64; 3], [i64; 3])> {\n        if let Some(bounds) = self.bounds {\n            return Ok(bounds);\n        }\n        let grid = ctx.grids().get(self.grid)?.ok_or(\"this mod's grid is gone\")?;\n        let bounds = ([grid.low.x, grid.low.y, grid.low.z], [grid.high.x, grid.high.y, grid.high.z]);\n        self.bounds = Some(bounds);\n        Ok(bounds)\n    }\n\n    fn count(&mut self, ctx: &Ctx) -> Result<()> {\n        let (low, high) = self.bounds(ctx)?;\n        let mut present = 0;\n        for at in chunks(low, high, MAX_CHUNKS) {\n            present += ctx.world().actors(at)?.len();\n        }\n        self.present = present;\n        self.counted_at = ctx.now_ms();\n        Ok(())\n    }\n}\n\nimpl Hub for Beacon {\n    fn spawn(ctx: &Ctx, _seed: &[u8]) -> Result<Self> {\n        let grid = ctx.key.parse().map_err(|_| Error::new(\"a mod's key is its grid id\"))?;\n        ctx.timer_every(\"count\", COUNT_EVERY_MS)?;\n        Ok(Self { grid, ..Self::default() })\n    }\n\n    fn load(_ctx: &Ctx, snapshot: &[u8], _from_version: u64) -> Result<Self> {\n        decode(snapshot)\n    }\n\n    fn persist(&mut self, _ctx: &Ctx) -> Result<Vec<u8>> {\n        encode(self)\n    }\n\n    fn handle(&mut self, _ctx: &Ctx, call: Call<'_>) -> Result<Vec<u8>> {\n        match call.method {\n            \"present\" => encode(&Present { present: self.present }),\n            \"state\" => encode(&*self),\n            other => Err(Error::unknown_method(other)),\n        }\n    }\n\n    fn on_timer(&mut self, ctx: &Ctx, _timer: &str) -> Result<()> {\n        self.count(ctx)\n    }\n\n    fn on_world(&mut self, ctx: &Ctx, events: &[WorldEvent]) -> Result<()> {\n        if actors_moved(events) {\n            self.count(ctx)?;\n        }\n        Ok(())\n    }\n}\n\nckx_sdk::export_hub!(Beacon);\n\n#[cfg(test)]\nmod tests {\n    use super::*;\n\n    fn ctx(key: &str) -> Ctx {\n        Ctx { app: 7171, instance: 1, epoch: 1, version: 1, kind: Kind::Hub, node_type: \"mod:beacon\".into(), key: key.into() }\n    }\n\n    fn event(kind: &str) -> WorldEvent {\n        WorldEvent { grid: 5, kind: kind.into(), chunk: [0, 0, 0] }\n    }\n\n    #[test]\n    fn a_grid_is_counted_chunk_by_chunk_within_a_cap() {\n        assert_eq!(chunks([4, 0, -2], [4, 0, -2], MAX_CHUNKS), vec![ChunkPos::new(4, 0, -2)]);\n        let six = chunks([0, 0, 0], [2, 0, 1], MAX_CHUNKS);\n        assert_eq!(six.len(), 6);\n        assert_eq!((six[1], six[3]), (ChunkPos::new(1, 0, 0), ChunkPos::new(0, 0, 1)), \"x fastest\");\n        assert_eq!(chunks([0, 0, 0], [99, 99, 99], MAX_CHUNKS).len(), MAX_CHUNKS);\n    }\n\n    #[test]\n    fn only_actor_events_start_a_count() {\n        assert!(!actors_moved(&[event(WorldEvent::VOXELS)]));\n        assert!(actors_moved(&[event(WorldEvent::VOXELS), event(WorldEvent::ACTORS)]));\n        let mut beacon = Beacon { grid: 5, present: 2, ..Beacon::default() };\n        // Voxel changes do not touch the node API (which answers nothing outside a host).\n        beacon.on_world(&ctx(\"5\"), &[event(WorldEvent::VOXELS)]).unwrap();\n        assert!(beacon.on_world(&ctx(\"5\"), &[event(WorldEvent::ACTORS)]).is_err());\n        assert_eq!(beacon.present, 2, \"a failed count keeps the last one\");\n    }\n\n    #[test]\n    fn present_answers_the_last_count() {\n        #[derive(Deserialize)]\n        struct Reply {\n            present: usize,\n        }\n        let mut beacon = Beacon { grid: 5, present: 3, counted_at: 9, ..Beacon::default() };\n        let reply: Reply =\n            decode(&beacon.handle(&ctx(\"5\"), Call { caller: Caller::Player(42), method: \"present\", payload: &[] }).unwrap()).unwrap();\n        assert_eq!(reply.present, 3);\n        let state: Beacon =\n            decode(&beacon.handle(&ctx(\"5\"), Call { caller: Caller::Player(42), method: \"state\", payload: &[] }).unwrap()).unwrap();\n        assert_eq!(state, beacon);\n        assert!(beacon.handle(&ctx(\"5\"), Call { caller: Caller::Player(42), method: \"nope\", payload: &[] }).is_err());\n    }\n\n    #[test]\n    fn the_key_is_the_grid_id() {\n        assert!(Beacon::spawn(&ctx(\"not-a-grid\"), &[]).is_err());\n        let beacon = Beacon::spawn(&ctx(\"91159989710848\"), &[]).unwrap();\n        assert_eq!(beacon.grid, 91_159_989_710_848);\n        let mut back: Beacon = Beacon::load(&ctx(\"91159989710848\"), &encode(&beacon).unwrap(), 1).unwrap();\n        assert_eq!(back.persist(&ctx(\"91159989710848\")).unwrap(), encode(&beacon).unwrap());\n    }\n}\n",
  },
  "construct-pool-cue": {
    "Cargo.toml": "[package]\nname = \"construct-pool-cue\"\ndescription = \"Pool cue: a mod that builds a pool table in voxels and strokes the cue at the white ball\"\nversion = \"0.1.0\"\nedition = \"2024\"\npublish = false\n\n[lib]\ncrate-type = [\"cdylib\", \"rlib\"]\n\n[dependencies]\n# Crowdy Studio's build replaces this line with the platform's copy of ckx-sdk.\nckx-sdk = \"0.6.0\"\nserde = { version = \"1\", features = [\"derive\"] }\n",
    "src/lib.rs": "//! Pool cue: a table with three balls in the middle of the mod's grid, and a cue that strokes at\n//! the white ball once a second while someone stands in that chunk. It is built from voxels, so\n//! passers-by who never accepted a CLIENT mod see the same table.\n//!\n//! The legacy SERVER template drew a felt box, sphere balls and a procedural-mesh cue as a\n//! construct.scene.v1 scene, sent as realtime server events, which a mod cannot send. This one\n//! builds the table once with `world.set_voxels` (at most 16 voxels a call, so in batches; it\n//! needs `update_voxel_data` on the grid, as a claim gives its owner) and moves the cue in whole\n//! blocks. The blocks stay in the chunk when the mod stops.\n//!\n//! Endpoints: `state`.\n\nuse ckx_sdk::node::MAX_VOXEL_WRITES;\nuse ckx_sdk::prelude::*;\n\nconst STROKE_MS: u64 = 1_000;\n/// Look again at who is here every this many strokes: world events can be lost.\nconst LOOK_EVERY: u64 = 10;\n/// Voxel types from the holodeck's palette.\nconst AIR: u16 = 0;\nconst FELT: u16 = 1;\nconst WOOD: u16 = 2;\nconst WHITE: u16 = 3;\nconst YELLOW: u16 = 7;\nconst BLACK: u16 = 12;\n\ntype Voxel = ((i16, i16, i16), u16);\n\n#[derive(Serialize, Deserialize, Default, Debug, PartialEq)]\npub struct Table {\n    pub grid: u64,\n    /// The grid's low chunk, read once.\n    pub origin: Option<[i64; 3]>,\n    /// The table and balls are in the chunk; voxels outlive a restart, so this is kept.\n    pub built: bool,\n    pub stroke: u64,\n    pub ticks: u64,\n    /// Actors in the low chunk when last looked; looked at again after a restart.\n    #[serde(skip_deserializing)]\n    pub present: usize,\n    /// Whether this run has drawn the whole cue yet.\n    #[serde(skip_deserializing)]\n    pub drawn: bool,\n}\n\n/// The table, within the grid's low chunk: a felt top on four wooden legs, and the white, a yellow\n/// and the black ball on it.\npub fn table() -> Vec<Voxel> {\n    let mut voxels: Vec<Voxel> = [(6, 7), (10, 7), (6, 9), (10, 9)].into_iter().map(|(x, z)| ((x, 0, z), WOOD)).collect();\n    for x in 6..=10 {\n        for z in 7..=9 {\n            voxels.push(((x, 1, z), FELT));\n        }\n    }\n    voxels.extend([((7, 2, 8), WHITE), ((9, 2, 7), YELLOW), ((9, 2, 9), BLACK)]);\n    voxels\n}\n\n/// The cue at `stroke`, three places along x in line with the white ball: pulled back on even\n/// strokes, its tip against the ball on odd ones.\npub fn cue(stroke: u64) -> [Voxel; 3] {\n    let forward = stroke % 2 == 1;\n    [((4, 2, 8), if forward { AIR } else { WOOD }), ((5, 2, 8), WOOD), ((6, 2, 8), if forward { WOOD } else { AIR })]\n}\n\n/// The batches of writes for `stroke`: the table if it is not built, the whole cue on a run's first\n/// stroke, then only the cue's two ends.\npub fn batches(origin: ChunkPos, stroke: u64, built: bool, drawn: bool) -> Vec<Vec<VoxelWrite>> {\n    let put = |(voxel, voxel_type): Voxel| VoxelWrite { chunk: origin, voxel, voxel_type, state: None };\n    let mut all: Vec<VoxelWrite> = if built { Vec::new() } else { table().into_iter().map(put).collect() };\n    let [back, middle, tip] = cue(stroke);\n    if built && drawn {\n        all.extend([put(back), put(tip)]);\n    } else {\n        all.extend([put(back), put(middle), put(tip)]);\n    }\n    all.chunks(MAX_VOXEL_WRITES).map(<[VoxelWrite]>::to_vec).collect()\n}\n\nimpl Table {\n    fn origin(&mut self, ctx: &Ctx) -> Result<ChunkPos> {\n        let [x, y, z] = match self.origin {\n            Some(origin) => origin,\n            None => {\n                let grid = ctx.grids().get(self.grid)?.ok_or(\"this mod's grid is gone\")?;\n                *self.origin.insert([grid.low.x, grid.low.y, grid.low.z])\n            }\n        };\n        Ok(ChunkPos::new(x, y, z))\n    }\n\n    fn look(&mut self, ctx: &Ctx) -> Result<()> {\n        let origin = self.origin(ctx)?;\n        self.present = ctx.world().actors(origin)?.len();\n        Ok(())\n    }\n\n    fn stroke(&mut self, ctx: &Ctx) -> Result<()> {\n        self.ticks += 1;\n        if self.ticks.is_multiple_of(LOOK_EVERY) {\n            self.look(ctx)?;\n        }\n        if self.present == 0 {\n            return Ok(());\n        }\n        let next = self.stroke + 1;\n        for batch in batches(self.origin(ctx)?, next, self.built, self.drawn) {\n            ctx.world().set_voxels(&batch)?;\n        }\n        (self.stroke, self.built, self.drawn) = (next, true, true);\n        Ok(())\n    }\n}\n\nimpl Hub for Table {\n    fn spawn(ctx: &Ctx, _seed: &[u8]) -> Result<Self> {\n        let grid = ctx.key.parse().map_err(|_| Error::new(\"a mod's key is its grid id\"))?;\n        ctx.timer_every(\"stroke\", STROKE_MS)?;\n        Ok(Self { grid, ..Self::default() })\n    }\n\n    fn load(_ctx: &Ctx, snapshot: &[u8], _from_version: u64) -> Result<Self> {\n        decode(snapshot)\n    }\n\n    fn persist(&mut self, _ctx: &Ctx) -> Result<Vec<u8>> {\n        encode(self)\n    }\n\n    fn handle(&mut self, _ctx: &Ctx, call: Call<'_>) -> Result<Vec<u8>> {\n        match call.method {\n            \"state\" => encode(&*self),\n            other => Err(Error::unknown_method(other)),\n        }\n    }\n\n    fn on_timer(&mut self, ctx: &Ctx, _timer: &str) -> Result<()> {\n        self.stroke(ctx)\n    }\n\n    fn on_world(&mut self, ctx: &Ctx, events: &[WorldEvent]) -> Result<()> {\n        let origin = self.origin(ctx)?;\n        if events.iter().any(|e| e.kind == WorldEvent::ACTORS && e.chunk == [origin.x, origin.y, origin.z]) {\n            self.look(ctx)?;\n        }\n        Ok(())\n    }\n}\n\nckx_sdk::export_hub!(Table);\n\n#[cfg(test)]\nmod tests {\n    use super::*;\n\n    const ORIGIN: ChunkPos = ChunkPos::new(3, 0, -2);\n\n    fn ctx() -> Ctx {\n        Ctx { app: 7171, instance: 1, epoch: 1, version: 1, kind: Kind::Hub, node_type: \"mod:pool\".into(), key: \"5\".into() }\n    }\n\n    fn placed(batch: &[VoxelWrite]) -> Vec<Voxel> {\n        batch.iter().map(|w| (w.voxel, w.voxel_type)).collect()\n    }\n\n    #[test]\n    fn the_table_is_felt_on_legs_with_three_balls() {\n        let t = table();\n        assert_eq!(t.len(), 22);\n        assert_eq!(t.iter().filter(|(_, v)| *v == FELT).count(), 15);\n        assert_eq!(t.iter().filter(|((_, y, _), v)| *v == WOOD && *y == 0).count(), 4);\n        assert!(t.contains(&((7, 2, 8), WHITE)) && t.contains(&((9, 2, 9), BLACK)));\n    }\n\n    #[test]\n    fn the_cue_strokes_at_the_white_ball() {\n        assert_eq!(cue(0), [((4, 2, 8), WOOD), ((5, 2, 8), WOOD), ((6, 2, 8), AIR)]);\n        assert_eq!(cue(1), [((4, 2, 8), AIR), ((5, 2, 8), WOOD), ((6, 2, 8), WOOD)]);\n        assert_eq!(cue(2), cue(0));\n    }\n\n    #[test]\n    fn a_build_fits_the_voxel_limit_and_later_strokes_move_two_blocks() {\n        let build = batches(ORIGIN, 1, false, false);\n        assert_eq!(build.iter().map(Vec::len).collect::<Vec<_>>(), [16, 9]);\n        assert!(build.iter().flatten().all(|w| w.chunk == ORIGIN && w.state.is_none()));\n        assert_eq!(placed(&batches(ORIGIN, 1, true, false)[0]), cue(1));\n        assert_eq!(placed(&batches(ORIGIN, 2, true, true)[0]), [((4, 2, 8), WOOD), ((6, 2, 8), AIR)]);\n    }\n\n    #[test]\n    fn it_only_strokes_while_someone_is_here() {\n        let mut t = Table { grid: 5, origin: Some([3, 0, -2]), built: true, ..Table::default() };\n        t.on_timer(&ctx(), \"stroke\").unwrap();\n        assert_eq!((t.ticks, t.stroke), (1, 0));\n        t.present = 1;\n        assert!(t.on_timer(&ctx(), \"stroke\").is_err(), \"outside a host the node API answers nothing\");\n        assert_eq!((t.stroke, t.drawn), (0, false));\n        let here = WorldEvent { grid: 5, kind: WorldEvent::ACTORS.into(), chunk: [3, 0, -2] };\n        assert!(t.on_world(&ctx(), &[here]).is_err());\n        let voxels = WorldEvent { grid: 5, kind: WorldEvent::VOXELS.into(), chunk: [3, 0, -2] };\n        t.on_world(&ctx(), &[voxels]).unwrap();\n    }\n\n    #[test]\n    fn a_restart_keeps_the_table_and_redraws_the_cue() {\n        let t = Table { grid: 5, origin: Some([3, 0, -2]), built: true, stroke: 3, ticks: 30, present: 1, drawn: true };\n        let back: Table = decode(&encode(&t).unwrap()).unwrap();\n        assert_eq!((back.built, back.stroke, back.present, back.drawn), (true, 3, 0, false));\n        assert!(Table::spawn(&Ctx { key: \"x\".into(), ..ctx() }, &[]).is_err());\n        assert_eq!(Table::spawn(&ctx(), &[]).unwrap().grid, 5);\n    }\n}\n",
  },
  "construct-spinning-child": {
    "Cargo.toml": "[package]\nname = \"construct-spinning-child\"\ndescription = \"Spinning child: a mod that builds a post with an arm swinging round it, in voxels\"\nversion = \"0.1.0\"\nedition = \"2024\"\npublish = false\n\n[lib]\ncrate-type = [\"cdylib\", \"rlib\"]\n\n[dependencies]\n# Crowdy Studio's build replaces this line with the platform's copy of ckx-sdk.\nckx-sdk = \"0.6.0\"\nserde = { version = \"1\", features = [\"derive\"] }\n",
    "src/lib.rs": "//! Spinning child: a post in the middle of the mod's grid with an arm that swings round it, a\n//! quarter turn a second while someone stands in that chunk. It is built from voxels, so every\n//! player who can see the grid sees it, whether or not they run a CLIENT mod.\n//!\n//! The legacy SERVER template drew a box and its spinning child as a construct.scene.v1 scene,\n//! sent as realtime server events. A mod sends no realtime events, so this one writes voxels\n//! (`world.set_voxels`, which needs `update_voxel_data` on the grid, as a claim gives its owner):\n//! whole blocks instead of a smooth rotation, and the blocks stay in the chunk when the mod stops.\n//!\n//! Endpoints: `state`.\n\nuse ckx_sdk::prelude::*;\n\nconst STEP_MS: u64 = 1_000;\n/// Look again at who is here every this many steps: world events can be lost.\nconst LOOK_EVERY: u64 = 10;\n/// Voxel types from the holodeck's palette.\nconst AIR: u16 = 0;\nconst WOOD: u16 = 2;\nconst WHITE: u16 = 3;\nconst PINK: u16 = 5;\n/// The post's foot and the hub the arm turns round, within the grid's low chunk.\nconst POST: (i16, i16, i16) = (8, 0, 8);\nconst HUB: (i16, i16, i16) = (8, 1, 8);\n\n#[derive(Serialize, Deserialize, Default, Debug, PartialEq)]\npub struct Spinner {\n    pub grid: u64,\n    /// The grid's low chunk, read once.\n    pub origin: Option<[i64; 3]>,\n    pub step: u64,\n    pub ticks: u64,\n    /// Actors in the low chunk when last looked; looked at again after a restart.\n    #[serde(skip_deserializing)]\n    pub present: usize,\n    /// Whether this run has drawn the whole spinner yet.\n    #[serde(skip_deserializing)]\n    pub drawn: bool,\n}\n\n/// Where the arm is at `step`: beside the hub, a quarter turn further each step.\npub fn arm(step: u64) -> (i16, i16, i16) {\n    let (x, y, z) = HUB;\n    match step % 4 {\n        0 => (x + 1, y, z),\n        1 => (x, y, z + 1),\n        2 => (x - 1, y, z),\n        _ => (x, y, z - 1),\n    }\n}\n\n/// The writes that put the arm at `step`: on a run's first step the whole spinner (the post, the\n/// hub and every place the arm can be, so nothing is left over from an earlier run), then only the\n/// arm's last place and its new one.\npub fn writes(origin: ChunkPos, step: u64, drawn: bool) -> Vec<VoxelWrite> {\n    let put = |voxel, voxel_type| VoxelWrite { chunk: origin, voxel, voxel_type, state: None };\n    if drawn {\n        return vec![put(arm(step + 3), AIR), put(arm(step), PINK)];\n    }\n    let mut all = vec![put(POST, WOOD), put(HUB, WHITE)];\n    all.extend((0..4).map(|turn| put(arm(turn), if turn == step % 4 { PINK } else { AIR })));\n    all\n}\n\nimpl Spinner {\n    fn origin(&mut self, ctx: &Ctx) -> Result<ChunkPos> {\n        let [x, y, z] = match self.origin {\n            Some(origin) => origin,\n            None => {\n                let grid = ctx.grids().get(self.grid)?.ok_or(\"this mod's grid is gone\")?;\n                *self.origin.insert([grid.low.x, grid.low.y, grid.low.z])\n            }\n        };\n        Ok(ChunkPos::new(x, y, z))\n    }\n\n    fn look(&mut self, ctx: &Ctx) -> Result<()> {\n        let origin = self.origin(ctx)?;\n        self.present = ctx.world().actors(origin)?.len();\n        Ok(())\n    }\n\n    fn step(&mut self, ctx: &Ctx) -> Result<()> {\n        self.ticks += 1;\n        if self.ticks.is_multiple_of(LOOK_EVERY) {\n            self.look(ctx)?;\n        }\n        if self.present == 0 {\n            return Ok(());\n        }\n        let next = self.step + 1;\n        ctx.world().set_voxels(&writes(self.origin(ctx)?, next, self.drawn))?;\n        (self.step, self.drawn) = (next, true);\n        Ok(())\n    }\n}\n\nimpl Hub for Spinner {\n    fn spawn(ctx: &Ctx, _seed: &[u8]) -> Result<Self> {\n        let grid = ctx.key.parse().map_err(|_| Error::new(\"a mod's key is its grid id\"))?;\n        ctx.timer_every(\"step\", STEP_MS)?;\n        Ok(Self { grid, ..Self::default() })\n    }\n\n    fn load(_ctx: &Ctx, snapshot: &[u8], _from_version: u64) -> Result<Self> {\n        decode(snapshot)\n    }\n\n    fn persist(&mut self, _ctx: &Ctx) -> Result<Vec<u8>> {\n        encode(self)\n    }\n\n    fn handle(&mut self, _ctx: &Ctx, call: Call<'_>) -> Result<Vec<u8>> {\n        match call.method {\n            \"state\" => encode(&*self),\n            other => Err(Error::unknown_method(other)),\n        }\n    }\n\n    fn on_timer(&mut self, ctx: &Ctx, _timer: &str) -> Result<()> {\n        self.step(ctx)\n    }\n\n    fn on_world(&mut self, ctx: &Ctx, events: &[WorldEvent]) -> Result<()> {\n        let origin = self.origin(ctx)?;\n        if events.iter().any(|e| e.kind == WorldEvent::ACTORS && e.chunk == [origin.x, origin.y, origin.z]) {\n            self.look(ctx)?;\n        }\n        Ok(())\n    }\n}\n\nckx_sdk::export_hub!(Spinner);\n\n#[cfg(test)]\nmod tests {\n    use super::*;\n\n    const ORIGIN: ChunkPos = ChunkPos::new(3, 0, -2);\n\n    fn ctx() -> Ctx {\n        Ctx { app: 7171, instance: 1, epoch: 1, version: 1, kind: Kind::Hub, node_type: \"mod:spinner\".into(), key: \"5\".into() }\n    }\n\n    fn placed(writes: &[VoxelWrite]) -> Vec<((i16, i16, i16), u16)> {\n        writes.iter().map(|w| (w.voxel, w.voxel_type)).collect()\n    }\n\n    #[test]\n    fn the_arm_goes_round_the_hub_a_quarter_turn_a_step() {\n        let places: Vec<_> = (0..4).map(arm).collect();\n        assert_eq!(places, [(9, 1, 8), (8, 1, 9), (7, 1, 8), (8, 1, 7)]);\n        assert_eq!(arm(4), arm(0));\n    }\n\n    #[test]\n    fn a_run_draws_everything_once_then_moves_only_the_arm() {\n        let first = writes(ORIGIN, 1, false);\n        assert!(first.iter().all(|w| w.chunk == ORIGIN && w.state.is_none()));\n        assert_eq!(placed(&first), [(POST, WOOD), (HUB, WHITE), (arm(0), AIR), (arm(1), PINK), (arm(2), AIR), (arm(3), AIR)]);\n        assert_eq!(placed(&writes(ORIGIN, 2, true)), [(arm(1), AIR), (arm(2), PINK)]);\n        assert_eq!(placed(&writes(ORIGIN, 4, true)), [(arm(3), AIR), (arm(0), PINK)], \"round again\");\n        assert!(first.len() <= ckx_sdk::node::MAX_VOXEL_WRITES);\n    }\n\n    #[test]\n    fn it_only_turns_while_someone_is_here() {\n        let mut s = Spinner { grid: 5, origin: Some([3, 0, -2]), ..Spinner::default() };\n        s.on_timer(&ctx(), \"step\").unwrap();\n        assert_eq!((s.ticks, s.step), (1, 0), \"nobody here: no writes, no node API\");\n        s.present = 1;\n        // Outside a host the node API answers nothing, so the write fails and the arm stays put.\n        assert!(s.on_timer(&ctx(), \"step\").is_err());\n        assert_eq!((s.step, s.drawn), (0, false));\n        let elsewhere = WorldEvent { grid: 5, kind: WorldEvent::ACTORS.into(), chunk: [9, 9, 9] };\n        s.on_world(&ctx(), &[elsewhere]).unwrap();\n        let here = WorldEvent { grid: 5, kind: WorldEvent::ACTORS.into(), chunk: [3, 0, -2] };\n        assert!(s.on_world(&ctx(), &[here]).is_err(), \"an arrival here looks again\");\n    }\n\n    #[test]\n    fn a_restart_looks_again_and_redraws() {\n        let s = Spinner { grid: 5, origin: Some([3, 0, -2]), step: 7, ticks: 70, present: 2, drawn: true };\n        let state: Spinner = decode(&encode(&s).unwrap()).unwrap();\n        assert_eq!((state.step, state.present, state.drawn), (7, 0, false));\n        assert!(Spinner::spawn(&Ctx { key: \"no\".into(), ..ctx() }, &[]).is_err());\n        assert_eq!(Spinner::spawn(&ctx(), &[]).unwrap().grid, 5);\n    }\n}\n",
  },
};
